function bind(){document.querySelectorAll('[data-menu]').forEach(e=>e.onclick=toggleRight);document.querySelectorAll('[data-settings]').forEach(e=>e.onclick=toggleLeft);document.querySelectorAll('[data-home]').forEach(e=>e.onclick=()=>go('home'));document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>go(e.dataset.go));document.querySelectorAll('[data-empty]').forEach(e=>e.onclick=()=>{S.draft={};save();go('newrepair')});document.querySelectorAll('[data-sheet]').forEach(e=>e.onclick=sheetBase);document.querySelectorAll('[data-client]').forEach(e=>e.onclick=()=>{S.draft.customer=S.lang==='ru'?'Иванов Сергей':'Ivanov Sergey';S.draft.phone='+7 999 123-45-67';save();go('newrepair')});document.querySelectorAll('[data-part]').forEach(e=>e.onclick=()=>{let[a,b]=e.dataset.part.split('|');S.draft.model='iPhone 15 Pro';S.draft.part=a;S.draft.price=b;save();go('newrepair')});document.querySelectorAll('[data-add]').forEach(e=>e.onclick=()=>{if(e.dataset.add==='customer'){S.draft.customer=S.lang==='ru'?'Иванов Сергей':'Ivanov Sergey';S.draft.phone='+7 999 123-45-67'}if(e.dataset.add==='model')S.draft.model='iPhone 15 Pro';if(e.dataset.add==='issue')S.draft.issue=S.lang==='ru'?'Разбит экран':'Broken screen';save();draft();bind()});document.querySelectorAll('[data-create]').forEach(e=>e.onclick=()=>toast(S.lang==='ru'?'Схематично: заказ создан':'Prototype: order created'));document.querySelectorAll('[data-open]').forEach(e=>e.onclick=()=>go(e.dataset.open));document.querySelectorAll('[data-photo]').forEach(e=>e.onclick=photo);document.querySelectorAll('[data-qr]').forEach(e=>e.onclick=qr);document.querySelectorAll('[data-search]').forEach(e=>e.onclick=()=>searchMode($('q')?$('q').value:''));document.querySelectorAll('[data-voice]').forEach(e=>e.onclick=voice);document.querySelectorAll('[data-fill]').forEach(e=>e.onclick=()=>{let v=e.dataset.fill;$('q').value=v;draw(v)});document.querySelectorAll('[data-clientres]').forEach(e=>e.onclick=()=>{S.draft.customer=S.lang==='ru'?'Иванов Сергей':'Ivanov Sergey';S.draft.phone='+7 999 123-45-67';save();hideSheet();go('newrepair')});document.querySelectorAll('[data-partres]').forEach(e=>e.onclick=()=>{let[a,b]=e.dataset.partres.split('|');S.draft.model='iPhone 15 Pro';S.draft.part=a;S.draft.price=b;save();hideSheet();go('newrepair')});document.querySelectorAll('[data-orderres]').forEach(e=>e.onclick=()=>{hideSheet();go('orders')});document.querySelectorAll('[data-fromphoto]').forEach(e=>e.onclick=()=>{S.draft.model='iPhone 15 Pro';S.draft.issue=S.lang==='ru'?'Разбит экран':'Broken screen';save();hideSheet();go('newrepair')});document.querySelectorAll('[data-fromqr]').forEach(e=>e.onclick=()=>{S.draft.customer=S.lang==='ru'?'Новый клиент':'New customer';S.draft.model='iPhone 14 Pro';save();hideSheet();go('newrepair')});document.querySelectorAll('[data-fromvoice]').forEach(e=>e.onclick=()=>{S.draft.customer=S.lang==='ru'?'Клиент голосом':'Voice customer';S.draft.phone='79991234567';S.draft.model='iPhone 14 Pro';S.draft.issue=S.lang==='ru'?'Не включается':'Does not turn on';save();hideSheet();go('newrepair')})}
$('lightB').onclick=()=>{S.theme='light';save();prefs();render()};$('darkB').onclick=()=>{S.theme='dark';save();prefs();render()};$('ruB').onclick=()=>{S.lang='ru';save();render()};$('enB').onclick=()=>{S.lang='en';save();render()};$('range').oninput=e=>{S.scale=+e.target.value;save();prefs()};$('minus').onclick=()=>{S.scale=Math.max(.9,S.scale-.05);save();prefs()};$('plus').onclick=()=>{S.scale=Math.min(1.25,S.scale+.05);save();prefs()};$('homeFromSettings').onclick=()=>{hideLeft();go('home')};document.querySelectorAll('[data-close="left"]').forEach(e=>e.onclick=hideLeft);document.querySelectorAll('[data-close="right"]').forEach(e=>e.onclick=hideRight);$('leftMask').onclick=e=>{if(e.target===$('leftMask'))hideLeft()};$('rightMask').onclick=e=>{if(e.target===$('rightMask'))hideRight()};$('sheetMask').onclick=hideSheet;$('bottomHandle').onclick=sheetBase;
let edge=null;document.addEventListener('pointerdown',e=>{if(e.clientX<18)edge=[e.clientX,e.clientY]});document.addEventListener('pointerup',e=>{if(edge&&e.clientX-edge[0]>55&&Math.abs(e.clientY-edge[1])<45)showRight();edge=null});
let rs=null;$('rightDrawer').addEventListener('pointerdown',e=>rs=e.clientX);$('rightDrawer').addEventListener('pointerup',e=>{if(rs!==null&&e.clientX-rs>45)hideRight();rs=null});
let hs=null;$('bottomHandle').addEventListener('pointerdown',e=>hs=e.clientY);$('bottomHandle').addEventListener('pointerup',e=>{if(hs!==null&&hs-e.clientY>18)sheetBase();hs=null});
let ss=null;$('sheet').addEventListener('pointerdown',e=>ss=e.clientY);$('sheet').addEventListener('pointerup',e=>{if(ss!==null&&e.clientY-ss>38)hideSheet();ss=null});
function render(){home();M.forEach(x=>generic(x[0]));draft();menu();prefs();go(S.page,false)}
render();
